import pandas as pd

def arrange_table_by_gender(genders: pd.DataFrame) -> pd.DataFrame:
    if genders.empty:
        return pd.DataFrame({'user_id': [], 'gender': []})
    order_map = {'female': 1, 'other': 2, 'male': 3}
    genders['g_order'] = genders['gender'].map(order_map)
    genders = genders.sort_values(['gender', 'user_id'])
    genders['rn'] = genders.groupby('gender').cumcount()
    sorted_df = genders.sort_values(['rn', 'g_order'])
    return sorted_df[['user_id', 'gender']]
